  "veraDiteFund.text[1]": { al: "zana e malit del.", en: "The zana of the mountain comes forth." },
  "veraDiteFund.text[2]": { al: "viti është i mirë.", en: "The year will be a good one." },
  "flocka1.text[2]": { al: "thonë: një burrë merr një floçkë në shtëpi. kur besa vdes, floçka kthehet në ujë.", en: "They say a man once took a floçkë home. When his besa was broken, she returned to the water." },
